import type { RgbValue } from '@/lib/color/types';

// APCA (Accessible Perceptual Contrast Algorithm) — the contrast method
// proposed for the still-draft WCAG 3. Ported from the reference
// implementation (Myndex/apca-w3, "SA98G" constants). Shown alongside the
// WCAG 2.1 ratio as a more perceptually accurate second opinion, not a
// replacement — WCAG 2.1 AA/AAA is still the enforceable standard today.
const SA98G = {
  mainTRC: 2.4,
  sRco: 0.2126729,
  sGco: 0.7151522,
  sBco: 0.072175,
  normBG: 0.56,
  normTXT: 0.57,
  revTXT: 0.62,
  revBG: 0.65,
  blkThrs: 0.022,
  blkClmp: 1.414,
  scaleBoW: 1.14,
  scaleWoB: 1.14,
  loBoWoffset: 0.027,
  loWoBoffset: 0.027,
  deltaYmin: 0.0005,
  loClip: 0.1,
};

function sRGBtoY(rgb: RgbValue): number {
  const exp = (channel: number) => Math.pow(channel / 255, SA98G.mainTRC);
  return SA98G.sRco * exp(rgb.r) + SA98G.sGco * exp(rgb.g) + SA98G.sBco * exp(rgb.b);
}

/**
 * Returns the signed APCA Lc (Lightness Contrast) score, roughly -108..106.
 * Positive = dark text on a light background; negative = light text on dark.
 */
export function getApcaScore(text: RgbValue, background: RgbValue): number {
  let txtY = sRGBtoY(text);
  let bgY = sRGBtoY(background);

  txtY = txtY > SA98G.blkThrs ? txtY : txtY + Math.pow(SA98G.blkThrs - txtY, SA98G.blkClmp);
  bgY = bgY > SA98G.blkThrs ? bgY : bgY + Math.pow(SA98G.blkThrs - bgY, SA98G.blkClmp);

  if (Math.abs(bgY - txtY) < SA98G.deltaYmin) return 0;

  let sapc: number;
  let output: number;

  if (bgY > txtY) {
    sapc = (Math.pow(bgY, SA98G.normBG) - Math.pow(txtY, SA98G.normTXT)) * SA98G.scaleBoW;
    output = sapc < SA98G.loClip ? 0 : sapc - SA98G.loBoWoffset;
  } else {
    sapc = (Math.pow(bgY, SA98G.revBG) - Math.pow(txtY, SA98G.revTXT)) * SA98G.scaleWoB;
    output = sapc > -SA98G.loClip ? 0 : sapc + SA98G.loWoBoffset;
  }

  return output * 100;
}

export function getApcaRatingText(absScore: number): string {
  if (absScore >= 90) return 'Excellent — fluent body text';
  if (absScore >= 75) return 'Good — body text';
  if (absScore >= 60) return 'Fair — large text only';
  if (absScore >= 45) return 'Weak — large/bold text only';
  if (absScore >= 15) return 'Poor — spot text only';
  return 'Fails — avoid';
}
