import type { RgbValue } from '@/lib/color/types';

export type CvdMode = 'normal' | 'protanopia' | 'deuteranopia' | 'tritanopia' | 'achromatopsia';

export const CVD_MODE_LABELS: Record<CvdMode, string> = {
  normal: 'Normal vision',
  protanopia: 'Protanopia',
  deuteranopia: 'Deuteranopia',
  tritanopia: 'Tritanopia',
  achromatopsia: 'Achromatopsia',
};

// Linear-RGB projection matrices for dichromacy simulation. Protanopia is
// Viénot 1999; deuteranopia is Machado, Oliveira & Fernandes 2009 (the same
// model Chromium DevTools uses for its vision-deficiency emulation);
// tritanopia uses one plane of Brettel 1997's two-plane projection as a
// single-matrix approximation. All three must be applied in *linear* RGB,
// not gamma-encoded sRGB, or the result skews badly.
const MATRICES: Record<Exclude<CvdMode, 'normal' | 'achromatopsia'>, number[][]> = {
  protanopia: [
    [0.10889, 0.89111, -0.00001],
    [0.10889, 0.89111, 0.00001],
    [0.00447, -0.00447, 1.0],
  ],
  deuteranopia: [
    [0.367, 0.861, -0.228],
    [0.28, 0.673, 0.047],
    [-0.012, 0.043, 0.969],
  ],
  tritanopia: [
    [1.01354, 0.14268, -0.15622],
    [-0.01181, 0.87561, 0.13619],
    [0.07707, 0.81208, 0.11085],
  ],
};

function srgbToLinear(c: number): number {
  const cs = c / 255;
  return cs <= 0.04045 ? cs / 12.92 : Math.pow((cs + 0.055) / 1.055, 2.4);
}

function linearToSrgb(c: number): number {
  const clamped = Math.min(1, Math.max(0, c));
  const v = clamped <= 0.0031308 ? clamped * 12.92 : 1.055 * Math.pow(clamped, 1 / 2.4) - 0.055;
  return Math.round(Math.min(1, Math.max(0, v)) * 255);
}

/**
 * Approximate simulation of how a color appears under a given color vision
 * deficiency — for illustration in the live preview, not a diagnostic tool.
 */
export function simulateColorBlindness(rgb: RgbValue, mode: CvdMode): RgbValue {
  if (mode === 'normal') return rgb;

  const linear = [srgbToLinear(rgb.r), srgbToLinear(rgb.g), srgbToLinear(rgb.b)];

  if (mode === 'achromatopsia') {
    const y = 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2];
    const v = linearToSrgb(y);
    return { r: v, g: v, b: v };
  }

  const m = MATRICES[mode];
  const out = m.map((row) => row[0] * linear[0] + row[1] * linear[1] + row[2] * linear[2]);
  return { r: linearToSrgb(out[0]), g: linearToSrgb(out[1]), b: linearToSrgb(out[2]) };
}
