import type { FC } from 'react';
import { getApcaRatingText } from '@/lib/contrast/apca';
import { getWcagRatingText } from '@/lib/contrast/wcag';

interface RatioDisplayProps {
  ratio: number;
  apcaScore: number;
}

const RatioDisplay: FC<RatioDisplayProps> = ({ ratio, apcaScore }) => {
  const absApca = Math.round(Math.abs(apcaScore));

  return (
    <div className="text-center">
      <span className="block text-5xl md:text-6xl font-display font-bold text-foreground">
        {ratio.toFixed(2)}:1
      </span>
      <span className="block text-sm text-muted-foreground mt-1">{getWcagRatingText(ratio)}</span>
      <span className="block text-[11px] text-muted-foreground/70 mt-0.5">WCAG 2.1 ratio</span>

      <div className="mt-5 pt-5 border-t border-border flex flex-col items-center">
        <span className="text-2xl font-display font-semibold text-foreground">
          {apcaScore > 0 ? '+' : apcaScore < 0 ? '−' : ''}
          {absApca} Lc
        </span>
        <span className="text-xs text-muted-foreground mt-0.5">{getApcaRatingText(absApca)}</span>
        <span className="text-[11px] text-muted-foreground/70 mt-0.5">
          APCA (draft WCAG 3 method) — a second opinion, not a certified standard yet
        </span>
      </div>
    </div>
  );
};

export default RatioDisplay;
